<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {ArrowLeft,Plus,RefreshCw,Search} from '@lucide/svelte';
 import {api,uploadTo} from './api';
 import {enter} from './motion';
 import ExportDocumentField from './ExportDocumentField.svelte';
 import {exportDate,moneyText,invoiceFileError,invoiceFileKey,uncertainInvoiceWrite,savedEbrcNumbers,reconciliationSelectionValid,reconciliationRegisterQuery,canonicalSavedEbrcNumber,reconciliationAlreadyCleared,type InvoiceFile} from './exportDocumentation';
 import type {Row} from './types';
 let {initialInvoice=0,dirty=$bindable(false),busy=$bindable(false),onopeninvoice}:{initialInvoice?:number;dirty?:boolean;busy?:boolean;onopeninvoice:(id:number)=>void}=$props();
 let records:Row[]=$state([]),detail:Row|null=$state(null),loaded=$state(false),error=$state(''),notice=$state(''),search=$state(''),status=$state('');
 let number=$state(''),previousNumber=$state(''),selectedNumber=$state(''),selectedFile=$state(''),queued:InvoiceFile[]=$state([]),numberUncertain=$state(false);
 let root:HTMLElement;
 let filtered=$derived(records.filter(record=>(!status||(record.documentation_cleared?.at?'cleared':'pending')===status)&&(!search||[record.invoice_number,record.party_name,record.profile?.shipping_bill_number,...savedEbrcNumbers(record)].join(' ').toLowerCase().includes(search.trim().toLowerCase()))));
 let actions=$derived.by(()=>detail?.actions||{}),permissions=$derived.by(()=>detail?.permissions||{});
 let files=$derived.by(()=>(detail?.files||[]).filter((file:Row)=>file.kind==='ebrc'));
 let uncertain=$derived(numberUncertain||queued.some(file=>file.status==='uncertain'));
 let canManage=$derived(!!actions.reconciliation_evidence);
 let canAttach=$derived(!!actions.reconciliation_attach),canRemove=$derived(!!actions.reconciliation_remove);
 const dateTime=(value:string)=>value?new Date(value).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'—';
 async function focus(id:string){await tick();root?.querySelector<HTMLElement>('#'+id)?.focus()}
 async function run(work:()=>Promise<void>){if(busy)return;busy=true;error='';try{await work()}catch(e){error=(e as Error).message;await focus('reconciliation-error')}finally{busy=false;loaded=true}}
 async function loadList(){const result=await api('/exports?'+reconciliationRegisterQuery());records=result.records||[]}
 async function refreshDetail(){
  if(!detail)return;
  const loaded:Row=await api('/exports/'+detail.record.id);detail=loaded;
  queued=queued.filter(file=>!loaded.files.some((saved:Row)=>saved.id===file.id));
  const numbers=savedEbrcNumbers(loaded.record),documents=loaded.files.filter((file:Row)=>file.kind==='ebrc');
  if(!numbers.includes(selectedNumber))selectedNumber=numbers.length===1?numbers[0]:'';
  if(!documents.some((file:Row)=>String(file.id)===selectedFile))selectedFile=documents.length===1?String(documents[0].id):'';
  await loadList();
 }
 async function open(id:number){if(busy)return;await run(async()=>{const result=await api('/exports/'+id);if(result.record.record_kind==='jv')throw new Error('Reconciliation is available for export invoices only.');detail=result;number='';selectedNumber=result.record.documentation_cleared?.ebrc_number||savedEbrcNumbers(result.record)[0]||'';previousNumber='';const documents=(result.files||[]).filter((file:Row)=>file.kind==='ebrc');selectedFile=result.record.documentation_cleared?.file_id?String(result.record.documentation_cleared.file_id):documents.length===1?String(documents[0].id):'';queued=[];numberUncertain=false;dirty=false;notice='';await focus('reconciliation-task-title')})}
 async function back(){if(busy)return;if(dirty&&!window.confirm('Leave unsaved eBRC input or queued documents? Saved invoice documents and clearance history remain.'))return;detail=null;number='';queued=[];dirty=false;numberUncertain=false;notice='';error='';await focus('reconciliation-register-title')}
 onMount(()=>{void run(loadList).then(()=>{if(initialInvoice)void open(initialInvoice)})});
 async function refresh(){await run(async()=>{if(detail){await refreshDetail();numberUncertain=false;notice='Saved eBRC details refreshed. Check the number and attachments before repeating an unconfirmed action.'}else await loadList()})}
 async function saveNumber(){
  if(busy||!detail||!canManage||uncertain)return;if(!number.trim()){error='Enter the eBRC number.';return}
  await run(async()=>{try{const result=await api(`/exports/${detail!.record.id}/reconciliation/ebrc`,{version:detail!.record.version,ebrc_number:number.trim(),...(previousNumber?{previous_ebrc_number:previousNumber}:{})});detail!.record.version=result.version;detail!.record.ebrcs=result.ebrcs;detail!.record.documentation_cleared=result.documentation_cleared;selectedNumber=canonicalSavedEbrcNumber(detail!.record,number);number='';previousNumber='';dirty=queued.length>0;await refreshDetail();notice='eBRC number saved. Attach its document or submit when the matching saved document is selected.'}catch(e){numberUncertain=uncertainInvoiceWrite(e);throw e}});
 }
 async function attach(event:Event){
  const input=event.currentTarget as HTMLInputElement,newFiles=Array.from(input.files||[]);input.value='';if(busy||!detail||!canAttach||uncertain)return;
  const invalid=newFiles.map(invoiceFileError).find(Boolean);if(invalid){error=invalid;return}
  if((detail.files||[]).length+queued.length+newFiles.length>100){error='An invoice can have at most 100 active documents.';return}
  for(const file of newFiles){const key=invoiceFileKey(file);if(!queued.some(entry=>entry.key===key))queued.push({file,key,kind:'ebrc',status:'queued'})}dirty=queued.length>0||!!number;
  await uploadQueued();
 }
 async function uploadQueued(){
  if(!detail||busy||!canAttach)return;
  await run(async()=>{for(const item of queued){if(item.status==='uploaded')continue;item.path??=`/exports/${detail!.record.id}/reconciliation/files?version=${detail!.record.version}&kind=ebrc`;item.status='uploading';item.error='';try{const result=await uploadTo(item.path,item.file);item.id=result.id;item.status='uploaded';selectedFile=String(result.id);detail!.record.version=result.version;detail!.record.documentation_cleared={}}catch(e){item.status=uncertainInvoiceWrite(e)?'uncertain':'failed';if(item.status==='failed')item.path=undefined;item.error=(e as Error).message;throw e}}await refreshDetail();dirty=!!number;notice='eBRC document attached.'});
 }
 function removeQueued(key:string){const item=queued.find(file=>file.key===key);if(busy||!item||item.path||!window.confirm(`Remove ${item.file.name} from the upload queue?`))return;queued=queued.filter(file=>file.key!==key);dirty=!!number||queued.length>0}
 async function removeFile(file:Row){
  if(busy||!detail||!canRemove||uncertain||!window.confirm(`Remove ${file.filename} from this invoice? The removal remains in the audit history and clears its documentation-cleared status.`))return;
  await run(async()=>{try{const result=await api(`/exports/${detail!.record.id}/reconciliation/files/${file.id}/remove`,{version:detail!.record.version});detail!.record.version=result.version;detail!.record.documentation_cleared={};detail!.files=detail!.files.filter((saved:Row)=>saved.id!==file.id);if(selectedFile===String(file.id))selectedFile='';await refreshDetail();notice='eBRC document removed. Documentation can be cleared again after its replacement is attached.'}catch(e){numberUncertain=uncertainInvoiceWrite(e);throw e}});
 }
 async function clear(){
  if(busy||!detail||!actions.reconcile||dirty||uncertain||reconciliationAlreadyCleared(detail.record,selectedNumber,Number(selectedFile))||!reconciliationSelectionValid(detail.record,files,selectedNumber,Number(selectedFile)))return;
  await run(async()=>{try{const result=await api(`/exports/${detail!.record.id}/reconcile`,{version:detail!.record.version,ebrc_number:selectedNumber,file_id:Number(selectedFile)});detail!.record.version=result.version;detail!.record.documentation_cleared=result.documentation_cleared;await refreshDetail();notice='Documentation cleared. Invoice approval and outstanding are unchanged.'}catch(e){numberUncertain=uncertainInvoiceWrite(e);throw e}});
 }
</script>

<section class="reconciliation-workspace" bind:this={root} aria-busy={busy}>
 {#if !detail}
  <header class="reconciliation-heading"><div><h1 id="reconciliation-register-title" tabindex="-1">Reconciliation</h1><p>All export invoices available to your account, with their eBRC documentation status.</p></div><button type="button" class="rc-button secondary" disabled={busy} onclick={refresh}><RefreshCw size={16}/>Refresh</button></header>
  <div class="reconciliation-filters"><label for="reconciliation-search">Search invoices<div class="rc-search"><Search size={16}/><input id="reconciliation-search" bind:value={search} placeholder="Invoice, company, shipping bill or eBRC"/></div></label><label for="reconciliation-status">Documentation status<select id="reconciliation-status" bind:value={status}><option value="">All invoices</option><option value="pending">eBRC pending</option><option value="cleared">Documentation cleared</option></select></label><strong>{filtered.length} invoices</strong></div>
  {#if error}<p id="reconciliation-error" class="rc-error" role="alert" tabindex="-1">{error}</p>{/if}
  <div class="rc-table"><table><thead><tr><th>Invoice number</th><th>Invoice date</th><th>Company / party</th><th>Shipping bill</th><th>Shipping bill date</th><th class="numeric">Amount</th><th>eBRC status</th></tr></thead><tbody>{#each filtered as record}<tr><td><button type="button" class="rc-reference" disabled={busy} onclick={()=>open(record.id)}>{record.invoice_number}</button></td><td>{exportDate(record.profile?.invoice_date)}</td><td>{record.party_name}</td><td>{record.profile?.shipping_bill_number||'—'}</td><td>{exportDate(record.profile?.shipping_bill_date)}</td><td class="numeric">{moneyText(record.invoice_amount,record.currency)}</td><td><span class:cleared={!!record.documentation_cleared?.at} class="rc-status">{record.documentation_cleared?.at?'Documentation cleared':'eBRC pending'}</span>{#if savedEbrcNumbers(record).length}<small>{savedEbrcNumbers(record).join(', ')}</small>{/if}</td></tr>{:else}<tr><td colspan="7"><div class="rc-empty"><h2>{!loaded?'Loading invoices…':error?'Invoices could not be loaded':search||status?'No matching invoices':'No export invoices available'}</h2><p>{!loaded?'Fetching invoices within your existing access.':error?'Use Refresh to try loading the register again.':search||status?'Change the search or status filter.':'Saved export invoices appear here automatically.'}</p></div></td></tr>{/each}</tbody></table></div>
 {:else}
  {@const record=detail.record}
  <button type="button" class="rc-back" disabled={busy} onclick={back}><ArrowLeft size={16}/>Reconciliation register</button>
  <header class="rc-task-heading"><div><h1 id="reconciliation-task-title" tabindex="-1">Reconcile · {record.invoice_number}</h1><p>{record.party_name}</p></div><div class="rc-actions"><button type="button" class="rc-button header" disabled={busy} onclick={refresh}><RefreshCw size={15}/>Refresh</button><button type="button" class="rc-button header" disabled={busy||dirty} onclick={()=>onopeninvoice(record.id)}>Open invoice</button></div></header>
  {#if error}<p id="reconciliation-error" class="rc-error" role="alert" tabindex="-1">{error}</p>{/if}{#if notice}<p class="rc-notice" role="status">{notice}</p>{/if}
  <div class="rc-task-body" use:enter={record.id}>
   <dl class="rc-saved-fields"><div><dt>Invoice number</dt><dd>{record.invoice_number}</dd></div><div><dt>Invoice date</dt><dd>{exportDate(record.profile?.invoice_date)}</dd></div><div><dt>Shipping bill number</dt><dd>{record.profile?.shipping_bill_number||'—'}</dd></div><div><dt>Shipping bill date</dt><dd>{exportDate(record.profile?.shipping_bill_date)}</dd></div><div><dt>Invoice amount</dt><dd>{moneyText(record.invoice_amount,record.currency)}</dd></div><div><dt>Documentation</dt><dd><span class="rc-status" class:cleared={!!record.documentation_cleared?.at}>{record.documentation_cleared?.at?'Cleared':'eBRC pending'}</span></dd></div></dl>
   <section class="rc-number-section"><h2>eBRC number</h2>{#if savedEbrcNumbers(record).length}<label for="reconciliation-number">Saved number<select id="reconciliation-number" bind:value={selectedNumber} disabled={busy}><option value="">Choose saved eBRC number</option>{#each savedEbrcNumbers(record) as value}<option value={value}>{value}</option>{/each}</select></label>{:else}<p>eBRC pending. Add the number when it is available.</p>{/if}
    {#if canManage}{#if selectedNumber&&!previousNumber}<button type="button" class="rc-button secondary" disabled={busy||dirty||uncertain} onclick={()=>{previousNumber=selectedNumber;number=selectedNumber;dirty=true;void focus('reconciliation-new-number')}}>Correct selected number</button>{/if}<div class="rc-number-entry"><label for="reconciliation-new-number">{previousNumber?'Correct eBRC number':savedEbrcNumbers(record).length?'Add another eBRC number':'Enter eBRC number'}<input id="reconciliation-new-number" bind:value={number} oninput={()=>dirty=!!number||queued.length>0} maxlength="160" disabled={busy||uncertain}/></label><button type="button" class="rc-button secondary" disabled={busy||uncertain||!number.trim()} onclick={saveNumber}><Plus size={15}/>{busy?'Saving…':previousNumber?'Save correction':'Save number'}</button>{#if previousNumber}<button type="button" class="rc-button secondary" disabled={busy||uncertain} onclick={()=>{previousNumber='';number='';dirty=queued.length>0}}>Cancel correction</button>{/if}</div>{/if}
   </section>
   <section class="rc-document-section"><h2>eBRC document</h2><p>Attach the certificate, then select the saved file that matches the eBRC number.</p><ExportDocumentField label="eBRC certificate" inputID="reconciliation-ebrc-document" {files} {queued} {canAttach} {canRemove} canDownload={!!permissions.download} {busy} {uncertain} onattach={attach} onremove={removeFile} onremovequeued={removeQueued}/>
    {#if queued.length}<button type="button" class="rc-button secondary" disabled={busy} onclick={uploadQueued}>Retry / confirm upload</button>{/if}
    {#if files.length}<label for="reconciliation-file">Document for this eBRC<select id="reconciliation-file" bind:value={selectedFile} disabled={busy}><option value="">Choose saved document</option>{#each files as file}<option value={String(file.id)}>{file.filename}</option>{/each}</select></label>{/if}
   </section>
   {#if record.documentation_cleared?.at}<p class="rc-notice"><strong>Documentation cleared</strong> · eBRC {record.documentation_cleared.ebrc_number} · {dateTime(record.documentation_cleared.at)}</p>{/if}
   {#if uncertain}<p class="rc-error">A request is unconfirmed. Refresh saved details before repeating it. Unconfirmed uploads retain their protected request.</p>{/if}
  </div>
  <footer class="rc-task-footer"><p>Documentation clearance keeps invoice approval and outstanding separate.</p>{#if actions.reconcile}<button type="button" class="rc-button primary" disabled={busy||dirty||uncertain||reconciliationAlreadyCleared(record,selectedNumber,Number(selectedFile))||!reconciliationSelectionValid(record,files,selectedNumber,Number(selectedFile))} onclick={clear}>{reconciliationAlreadyCleared(record,selectedNumber,Number(selectedFile))?'Documentation cleared':'Submit — invoice cleared'}</button>{/if}</footer>
 {/if}
</section>
<style>
 @media(min-width:1024px){
 .reconciliation-workspace{color:var(--ex-ink);min-width:0}.reconciliation-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;padding:26px 28px 20px}.reconciliation-workspace h1{font-size:24px;line-height:1.35;letter-spacing:-.02em;margin:0;font-weight:800}.reconciliation-heading p{font-size:13px;color:var(--ex-muted);line-height:1.6;max-width:75ch;margin:8px 0 0}.reconciliation-filters{display:flex;align-items:flex-end;gap:18px;padding:0 28px 24px}.reconciliation-filters>label:first-child{flex:1;max-width:500px}.reconciliation-filters>label:nth-child(2){width:220px}.reconciliation-filters>strong{font-size:12px;margin-left:auto;padding-bottom:12px}
 label{display:flex;flex-direction:column;gap:7px;font-size:12px;font-weight:700;min-width:0}input,select{box-sizing:border-box;width:100%;min-height:42px;border:1px solid #b8ccd4;border-radius:8px;padding:9px 11px;background:#eff5f8;color:var(--ex-ink);font:inherit;font-size:13px;line-height:1.5;caret-color:#087d76}input::placeholder{color:#56717e;opacity:1}.rc-search{position:relative}.rc-search :global(svg){position:absolute;left:12px;top:13px;color:var(--ex-muted)}.reconciliation-workspace .reconciliation-filters .rc-search input#reconciliation-search{padding-left:37px}
 .rc-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;border:1px solid transparent;border-radius:8px;padding:9px 13px;font:inherit;font-size:12px;font-weight:800;line-height:1.4;text-decoration:none;cursor:pointer;white-space:nowrap;background:none;color:var(--ex-ink)}.rc-button.primary{background:var(--ex-teal);color:#fff}.rc-button.primary:hover{background:#0c5954}.rc-button.secondary{background:#edf4f5;border-color:#bfced3;color:#183f50}.rc-button.secondary:hover{background:#deecec}.rc-button.header{background:#e8f0f3;border-color:#cadde4;color:#19374b}.rc-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}:is(button,input,select):disabled{opacity:.6;cursor:not-allowed}:is(button,input,select):focus-visible{outline:3px solid #58a9a1;outline-offset:3px}[tabindex='-1']:focus{outline:none}
 .rc-table{overflow:auto;scrollbar-width:thin;scrollbar-color:#91b3b3 #edf4f5}.rc-table table{border-collapse:collapse;width:100%;min-width:930px;font-variant-numeric:tabular-nums}.rc-table th,.rc-table td{padding:14px 17px;text-align:left;border-bottom:1px solid var(--ex-line);font-size:12px;line-height:1.5;vertical-align:middle}.rc-table th{background:#edf4f5;color:#365260;font-weight:800;white-space:nowrap}.rc-table .numeric{text-align:right;white-space:nowrap}.rc-table small{display:block;font-size:11px;margin-top:4px;color:var(--ex-muted)}.rc-reference{padding:0;border:0;background:none;color:var(--ex-teal);font:inherit;font-weight:800;text-decoration:underline;text-underline-offset:3px;cursor:pointer;text-align:left}.rc-status{display:inline-block;border-radius:6px;background:#fff3dc;color:#745311;padding:5px 8px;font-size:11px;font-weight:800;line-height:1.5}.rc-status.cleared{background:#e1f0e7;color:#205f48}.rc-empty{padding:35px 20px;text-align:center}.rc-empty h2{font-size:18px;margin:0 0 8px}.rc-empty p{color:var(--ex-muted);font-size:13px;line-height:1.6}
 .rc-error,.rc-notice{margin:16px 28px;padding:12px 15px;border-radius:8px;line-height:1.6;font-size:13px;overflow-wrap:anywhere}.rc-error{color:#8e2c27;background:#fbecea;border:1px solid #e8c8c4}.rc-notice{color:#185842;background:#e5f2e9;border:1px solid #c2ddcc}.rc-back{display:flex;align-items:center;gap:7px;font:inherit;font-size:13px;font-weight:800;color:var(--ex-teal);background:none;border:0;padding:18px 28px;cursor:pointer}.rc-task-heading{position:sticky;top:0;z-index:6;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:20px 28px;background:var(--ex-navy);color:#fff}.rc-task-heading h1{color:#fff;overflow-wrap:anywhere}.rc-task-heading p{font-size:13px;line-height:1.5;margin:7px 0 0;color:#d4e6ed}.rc-task-body{padding:24px 28px}.rc-saved-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px 24px;padding:18px;background:#f4f7f9;border-radius:8px;margin:0 0 24px}.rc-saved-fields dt{font-size:12px;color:var(--ex-muted);font-weight:700;margin-bottom:7px}.rc-saved-fields dd{font-size:13px;font-weight:600;line-height:1.5;margin:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.rc-number-section,.rc-document-section{border-top:1px solid var(--ex-line);padding:22px 0}.rc-task-body h2{font-size:17px;margin:0 0 16px;font-weight:800}.rc-task-body p{font-size:13px;color:var(--ex-muted);line-height:1.6;max-width:75ch}.rc-number-section>label,.rc-document-section>label{max-width:700px}.rc-number-entry{display:flex;align-items:flex-end;gap:12px;margin-top:16px;max-width:700px}.rc-number-entry>label{flex:1}.rc-document-section>label{margin-top:18px}.rc-task-body .rc-error,.rc-task-body .rc-notice{margin-left:0;margin-right:0}.rc-task-footer{position:sticky;bottom:0;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:16px 28px;background:#e8f0ec;border-top:1px solid #c2d3cb}.rc-task-footer p{font-size:12px;line-height:1.5;color:#446759;margin:0;max-width:65ch}
 }
</style>
